// 1. Get the incoming data from the previous node
// FIX: Using standard n8n reference syntax for safety
const inputItem = $input.first().json;

// 2. Extract the raw output text (contains the "Booking: {...}" JSON block)
const rawOutput = inputItem.output || "";

// 3. Parse the JSON block from the text
let data = {};
let isBookingFound = false;

try {
    // Find the JSON block after "Booking: "
    const jsonMatch = rawOutput.match(/Booking:\s*(\{.*\})/s);
    if (jsonMatch && jsonMatch[1]) {
        data = JSON.parse(jsonMatch[1]);
        isBookingFound = true;
    } else {
        // Try parsing the entire output as JSON
        data = JSON.parse(rawOutput);
        isBookingFound = true;
    }
} catch (e) {
    // Not a JSON block, treating as plain text conversational reply
    data = {};
    isBookingFound = false;
}

// 4. Extract test name from data
const testName = data.testName || "";

// 5. Convert 24hr + timezone to 12hr format (e.g., "14:00:00+05:00" → "2 PM")
function to12Hour(timeStr) {
    if (!timeStr) return "";

    const match = timeStr.match(/(\d{2}):(\d{2})/);
    if (!match) return "";

    const hours = parseInt(match[1], 10);
    const minutes = match[2];
    const ampm = hours >= 12 ? 'PM' : 'AM';
    const h12 = hours % 12 || 12;

    if (minutes !== "00") {
        return `${h12}:${minutes} ${ampm}`;
    }
    return `${h12} ${ampm}`;
}

// 6. Clean time values
const cleanStart = data.startTime || "";
const cleanEnd = data.endTime || "";
const startTime12h = to12Hour(cleanStart);
const endTime12h = to12Hour(cleanEnd);

// 7. Extract date from startTime (YYYY-MM-DD)
const appointmentDate = cleanStart ? cleanStart.substring(0, 10) : "";

// 8. Build description with all fixes
const detailedDescription = `Patient: ${data.patientName || ""}
Test: ${testName}
Mobile: ${data.mobile || ""}
Age: ${data.age || ""}
Gender: ${data.gender || ""}
Issue: ${data.issue || ""}
Referred By: ${data.doctorName || ""}
Fee: ${data.fee || data["Test Charges"] || data.testCharges || "0"}`;

// 9. Determine intent and conversational reply routing states
let finalIntent = data.intent || "";
let conversationalReply = "";

if (isBookingFound) {
    // Rule 1: If structured booking data exists, explicitly force intent
    finalIntent = "booking confirmed";
} else {
    // Rule 2: If it's normal chat text, pass it inside conversationalReply
    conversationalReply = rawOutput;
}

// 10. Return fixed output payload matching exactly what you requested
return {
    json: {
        authorized: true,
        Intent: finalIntent,                         // Forced to "booking confirmed" on valid parsing
        conversationalReply: conversationalReply,    // Holds raw reply if it's a normal chat string
        patientName: data.patientName || "",
        mobile: data.mobile || "",
        testName: testName,
        referredBy: data.doctorName || "",
        issue: data.issue || "",
        startTime: startTime12h,
        endTime: endTime12h,
        date: appointmentDate,
        googleStart: data.startTime || "",
        googleEnd: data.endTime || "",
        eventId: data.eventId || "",
        calendarId: data.calendarId || "primary",
        summary: data.summary || `${testName} - ${data.patientName || ""}`,
        description: detailedDescription,
        age: data.age || "",
        gender: data.gender || "",
        testCharges: data.fee || data["Test Charges"] || data.testCharges || "0"
    }
};

