// 1. Extract existing fields
const patientName = $json["Patient Name"] || "N/A";
const rowNum = $json["row_number"] || 0;
const fee = $json["Fee"] || "0";
const testName = $json["Test Name"] || "Lab Test";

// --- MOBILE NUMBER CONVERSION LOGIC ---
let rawMobile = ($json["Mobile Number"] || "").toString().trim();
let mobileNumber = rawMobile;

if (rawMobile.startsWith('0')) {
  mobileNumber = '92' + rawMobile.substring(1);
} else if (rawMobile.length > 0 && !rawMobile.startsWith('92')) {
  mobileNumber = '92' + rawMobile;
}
// --------------------------------------

// 2. Normalize Statuses
const paymentStatus = ($json["Payment Status"] || "").toString().trim().toUpperCase();
const messageStatus = ($json["Message Status"] || "").toString().trim().toUpperCase();
const sampleTaken = ($json["Sample Taken"] || "").toString().trim().toUpperCase();
const reportStatus = ($json["Report Status"] || "").toString().trim().toUpperCase();
const deliveryStatus = ($json["Report Delivery Status"] || "").toString().trim().toUpperCase();

// 3. Handle Reference ID Logic (STRICT)
let referenceId = $json["Reference_ID"] || $json["Reference ID"] || "";

// Only generate if it's truly empty AND paid
if (paymentStatus === "PAID" && (referenceId === "" || referenceId === null)) {
  const datePart = new Date().toISOString().slice(2, 10).replace(/-/g, ''); 
  const randomPart = Math.random().toString(36).substring(2, 5).toUpperCase();
  referenceId = `LAB-${datePart}-${randomPart}`;
}

// 4. Define Routing Logic
let routingKey = "no_action";

// ROUTE 1: Payment Receipt
if (paymentStatus === "PAID" && messageStatus !== "SENT") {
  routingKey = "send_receipt";
} 
// ROUTE 2: Update to In Process
else if (sampleTaken === "YES" && reportStatus !== "READY" && reportStatus !== "IN PROCESS") {
  routingKey = "update_in_process";
}
// ROUTE 3: Report Ready (PDF Delivery)
else if (reportStatus === "READY" && deliveryStatus !== "DELIVERED") {
  routingKey = "send_report";
}

// 5. Return Clean Data
return {
  patient_name: patientName,
  mobile_number: mobileNumber, // Now outputs in 923XXXXXXXXX format
  row_number: rowNum,
  fee: fee,
  test_name: testName,
  reference_id: referenceId, 
  routing_key: routingKey
};

// 1. Get Base64 from Gemini
const base64Data = $json.candidates[0].content.parts[0].inlineData.data;
const pcmBuffer = Buffer.from(base64Data, 'base64');

// 2. Create WAV Header (44 bytes) so Cloudinary recognizes it
const wavHeader = Buffer.alloc(44);
wavHeader.write('RIFF', 0);
wavHeader.writeUInt32LE(36 + pcmBuffer.length, 4);
wavHeader.write('WAVE', 8);
wavHeader.write('fmt ', 12);
wavHeader.writeUInt32LE(16, 16);
wavHeader.writeUInt16LE(1, 20); // PCM format
wavHeader.writeUInt16LE(1, 22); // Mono
wavHeader.writeUInt32LE(24000, 24); // Sample Rate (Gemini is 24kHz)
wavHeader.writeUInt32LE(24000 * 2, 28); // Byte Rate
wavHeader.writeUInt16LE(2, 32); // Block Align
wavHeader.writeUInt16LE(16, 34); // Bits per sample
wavHeader.write('data', 36);
wavHeader.writeUInt32LE(pcmBuffer.length, 40);

// 3. Combine Header + Raw Data
const finalBuffer = Buffer.concat([wavHeader, pcmBuffer]);

// 4. Register as a file for Cloudinary
const binaryData = await this.helpers.prepareBinaryData(
    finalBuffer, 
    'appointment_voice.mp3', 
    'audio/mpeg'
);

return [
  {
    json: { resource_type: "video" },
    binary: { data: binaryData }
  }
];

// 1. Target the incoming data from the active item loop
const items = $json;

// 2. Grab the text output sent from your AI Agent
const messageText = items.output || "";

// 3. Fallback to your current state tracking routing type
let determinedType = items["Message Type"] || "audio";

// 4. Convert text to lowercase once for accurate string checking
const lowerText = messageText.toLowerCase();

// 5. Check Rule A: Explicit Lab Action JSON Intents
const hasJsonIntent = lowerText.includes("booking confirmed") || 
                      lowerText.includes("booking rescheduled") || 
                      lowerText.includes("booking cancelled");

// 6. Check Rule B: Core Patient & Lab Test Confirmation Summaries
const hasSummaryLayout = lowerText.includes("patient name:") || 
                         lowerText.includes("test:") || 
                         lowerText.includes("charges:") ||
                         lowerText.includes("shall i confirm?");

// 7. Check Rule C: Lab Test Information & Slot Selection Announcements
const hasLabInfoList = lowerText.includes("preparation:") || 
                       lowerText.includes("reporting:") || 
                       lowerText.includes("available slots are:") ||
                       lowerText.includes("choose a slot by its number");

// 8. If any structured lab summary, slot checklist, or test details match, force Text route
if (hasJsonIntent || hasSummaryLayout || hasLabInfoList) {
    determinedType = "text";
}

// 9. Output the clean object back to your downstream workflow nodes
return {
    "output": messageText,
    "Message Type": determinedType,
    "Customer Number": items["Customer Number"] || "",
    "Session ID": items["Session ID"] || "",
    "Current_Department": items["Current_Department"] || "Lab Deptt"
};

// 1. Get the incoming data item
const incomingItems = $input.all();
let basePayload = {};

if (incomingItems && incomingItems.length > 0) {
  basePayload = incomingItems[0].json;
}

// 2. Extract the query string accurately from any incoming path variation
// This checks 'query', 'User Message', or 'text' based on your workflow paths
let finalQuery = basePayload["query"] || basePayload["User Message"] || basePayload["text"] || "";

// 3. Determine the Message Type dynamically
let messageType = basePayload["Message Type"] || (basePayload["text"] ? "audio" : "text");

// 4. Return ONLY the two requested keys in the output payload
return [{
  json: {
    "query": finalQuery,
    "Message Type": messageType
  }
}];
